def content(self):
    """Content of the response, in bytes."""

    if self._content is None:
        # Read the contents.
        try:
            if self._content_consumed:
                raise RuntimeError(
                    'The content for this response was already consumed')

            if self.status_code == 0:
                self._content = None
            else:
                self._content = b''.join(self.iter_content(CONTENT_CHUNK_SIZE)) or b''

        except AttributeError:
            self._content = None

    self._content_consumed = True
    # don't need to release the connection; that's been handled by urllib3
    # since we exhausted the data.
    return self._content

def iter_content(self, chunk_size=1, decode_unicode=False):
    """Iterates over the response data.  When stream=True is set on the
    request, this avoids reading the content at once into memory for
    large responses.  The chunk size is the number of bytes it should
    read into memory.  This is not necessarily the length of each item
    returned as decoding can take place.

    If decode_unicode is True, content will be decoded using the best
    available encoding based on the response.
    """

    def generate():
        # Special case for urllib3.
        if hasattr(self.raw, 'stream'):
            try:
                for chunk in self.raw.stream(chunk_size, decode_content=True):
                    yield chunk
            except ProtocolError as e:
                raise ChunkedEncodingError(e)
            except DecodeError as e:
                raise ContentDecodingError(e)
            except ReadTimeoutError as e:
                raise ConnectionError(e)
        else:
            # Standard file-like object.
            while True:
                chunk = self.raw.read(chunk_size)
                if not chunk:
                    break
                yield chunk

        self._content_consumed = True

    if self._content_consumed and isinstance(self._content, bool):
        raise StreamConsumedError()
    elif not isinstance(chunk_size, int):
        raise TypeError("chunk_size must be an int, it is instead a %s." % type(chunk_size))
    # simulate reading small chunks of the content
    reused_chunks = iter_slices(self._content, chunk_size)

    stream_chunks = generate()

    chunks = reused_chunks if self._content_consumed else stream_chunks

    if decode_unicode:
        chunks = stream_decode_response_unicode(chunks, self)

    return chunks

def pytestconfig(request):
    """Session-scoped fixture that returns the :class:`_pytest.config.Config` object.

    Example::

        def test_foo(pytestconfig):
            if pytestconfig.getoption("verbose") > 0:
                ...

    """
    return request.config

def collect(self):
    if not getattr(self.obj, "__test__", True):
        return []

    # NB. we avoid random getattrs and peek in the __dict__ instead
    # (XXX originally introduced from a PyPy need, still true?)
    dicts = [getattr(self.obj, "__dict__", {})]
    for basecls in inspect.getmro(self.obj.__class__):
        dicts.append(basecls.__dict__)
    seen = {}
    values = []
    for dic in dicts:
        for name, obj in list(dic.items()):
            if name in seen:
                continue
            seen[name] = True
            res = self._makeitem(name, obj)
            if res is None:
                continue
            if not isinstance(res, list):
                res = [res]
            values.extend(res)
    values.sort(key=lambda item: item.reportinfo()[:2])
    return values

def assert_contains(self, entries):
    __tracebackhide__ = True
    i = 0
    entries = list(entries)
    backlocals = sys._getframe(1).f_locals
    while entries:
        name, check = entries.pop(0)
        for ind, call in enumerate(self.calls[i:]):
            if call._name == name:
                print("NAMEMATCH", name, call)
                if eval(check, backlocals, call.__dict__):
                    print("CHECKERMATCH", repr(check), "->", call)
                else:
                    print("NOCHECKERMATCH", repr(check), "-", call)
                    continue
                i += ind + 1
                break
            print("NONAMEMATCH", name, "with", call)
        else:
            pytest.fail("could not find {!r} check {!r}".format(name, check))

def readouterr(self) -> CaptureResult:
    if self.out:
        out = self.out.snap()
    else:
        out = ""
    if self.err:
        err = self.err.snap()
    else:
        err = ""
    return CaptureResult(out, err)

def set_option(self, optname, value, action=None, optdict=None):
    """Overridden from config.OptionsProviderMixin to handle some
    special options
    """
    if optname in self._options_methods or optname in self._bw_options_methods:
        if value:
            try:
                meth = self._options_methods[optname]
            except KeyError:
                meth = self._bw_options_methods[optname]
                warnings.warn(
                    f"{optname} is deprecated, replace it by {optname.split('-')[0]}",
                    DeprecationWarning,
                )
            value = utils._check_csv(value)
            if isinstance(value, (list, tuple)):
                for _id in value:
                    meth(_id, ignore_unknown=True)
            else:
                meth(value)
            return  # no need to call set_option, disable/enable methods do it
    elif optname == "output-format":
        assert isinstance(
            value, str
        ), "'output-format' should be a comma separated string of reporters"
        self._load_reporters(value)
    try:
        checkers.BaseTokenChecker.set_option(self, optname, value, action, optdict)
    except config.UnsupportedAction:
        print(f"option {optname} can't be read from config file", file=sys.stderr)

def visit_importfrom(self, node: nodes.ImportFrom) -> None:
    """Checks to see if a module uses a non-Python logging module."""
    try:
        logging_name = self._from_imports[node.modname]
        for module, as_name in node.names:
            if module == logging_name:
                self._logging_names.add(as_name or module)
    except KeyError:
        self.add_message('invalid-logging-import', node=node)
    except Exception as e:
        self.error(f'Error processing import from {node.modname}: {e}')
